": ["decision_authority", "oversight_accountability"], "source_ids": ["justice"], "observations": [{"observation_id": "institutional_power_1850_1917_20261026:justice_baseline:1", "statement": "Senaatin oikeusosasto käsitteli ylempään oikeusasteeseen saapuneita asioita. Kuolemantuomioissa se antoi lausunnon keisarille, joka teki lopullisen päätöksen.", "source_ids": ["justice"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["senaatin oikeusosasto", "keisari", "hovioikeudet"], "affected_groups": ["oikeudenkävijät", "syytetyt"], "mechanism_hypothesis": "Oikeusasteiden ja hallitsijan tehtäväjako jäsensi oikeudellista päätösvaltaa.", "case_limitations": "1850 ei ole perustamisvuosi: kyse on keruujaksoon rajatusta jatkuvan järjestelyn kuvauksesta. Ei mittaa oikeusturvan yhdenvertaisuutta tai toteutunutta riippumattomuutta.", "formal_authority_status": "baseline_arrangement_not_new_event", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1850_1917_20261026:municipal1865", "primary_item_id": "kunnallishallinto-1865", "reuse_existing_item": true, "title": "Maaseudun kunnallinen päätösvalta eriytyy", "year_start": 1865, "year_end": 1865, "theme_ids": [8, 19, 28], "dimension_codes": ["decision_authority", "access_representation"], "source_ids": ["municipal"], "observations": [{"observation_id": "institutional_power_1850_1917_20261026:municipal1865:1", "statement": "Vuoden 1865 asetus loi maaseudun kunnallishallinnon järjestelyä. Kunnille kuuluvat talous- ja järjestysasiat erotettiin valtion viranomaisille kuuluvista tehtävistä.", "source_ids": ["municipal"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["kunta", "valtion viranomaiset"], "affected_groups": ["kuntalaiset"], "mechanism_hypothesis": "Paikallinen hallinto sai erillisen päätösareenan."