 28], "dimension_codes": ["decision_authority", "resource_control"], "source_ids": ["municipal"], "observations": [{"observation_id": "institutional_power_1850_1917_20261026:cities1873:1", "statement": "Kaupunkeja koskeva kunnallishallinnon asetus annettiin 1873. Rahatoimikamari hoiti kaupungin omaisuutta ja raha-asioita.", "source_ids": ["municipal"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["kaupungin toimielimet", "rahatoimikamari"], "affected_groups": ["kaupunkilaiset"], "mechanism_hypothesis": "Omaisuuden hallinta ja paikallinen päätöksenteko muodostivat kunnallisen resurssivallan kanavan.", "case_limitations": "Rahatoimikamarin asemaa ei rinnasteta myöhempään kaupunginhallitukseen; toteutuminen tarkistettava kaupunkikohtaisesti.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1850_1917_20261026:treasury1875", "primary_item_id": "institutional_power_1850_1917_20261026:treasury1875", "reuse_existing_item": false, "title": "Valtiokonttorin päätös ja toiminnan käynnistyminen", "year_start": 1875, "year_end": 1876, "theme_ids": [8, 17, 28], "dimension_codes": ["resource_control", "agenda_preparation"], "source_ids": ["finance"], "observations": [{"observation_id": "institutional_power_1850_1917_20261026:treasury1875:1", "statement": "Perustamisesitys hyväksyttiin 30.6.1875. Johtokunta aloitti joulukuussa; toiminta käynnistyi 1876. Tehtäviin kuului valtionrahastojen maksuja, sijoittamista ja ulkomaisten lainojen kuoletuksia.", "source_ids": ["finance"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["keisari", "senaatti", "Valtiokonttori"], "affected_groups": ["julkisten menojen saajat", "velkojat"], "mechanism_hypothesis": "Tehtävien eriyttäminen selkeytti rahastojen hallinnan vastuuketjua.", "case_limitations": "Hallinnollinen tehtävä ei ole vapaa budjettivalta. Menopäätös, maksatus ja rahoituksen hallinta erotetaan.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1850_1917_20261026:drafting1892", "primary_item_id": "institutional_power_1850_1917_20261026:drafting1892", "reuse_existing_item": false, "title": "Oikeustoimituskunta lainvalmistelun toimielimenä", "year_start": 1892, "year_end": 1917, "theme_ids": [8, 28, 29], "dimension_codes": ["agenda_preparation", "decision_authority"], "source_ids": ["justice"], "observations": [{"observation_id": "institutional_power_1850_1917_20261026:drafting1892:1", "statement": "Vuonna 1892 perustettu oikeustoimituskunta valmisteli lainsäädäntöaloitteita ja oikeusosastolle esiteltäviä asioita.", "source_ids": ["justice"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["senaatin oikeustoimituskunta", "oikeusosasto"], "affected_groups": ["lainsäädännön kohderyhmät"], "mechanism_hypothesis": "Valmistelijan mahdollisuus rajata vaihtoehtoja voi vaikuttaa lopulliseen ratkaisuun.", "case_limitations": "Valmistelu ei ole sama kuin lopullinen päätösvalta. Eri tehtävien toimivaltarajat ja tosiasiallinen aloitteellisuus tarvitsevat alkuperäiset asiakirjat.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1850_1917_20261026:manifest1899", "primary_item_id": "cleavages_1850_1917_20261023:address1899", "reuse_existing_item": true, "title": "Yleisvaltakunnallisen lain rooli ja adressin vaikuttamisraja", "year_start": 1899, "year_end": 1899, "theme_ids": [8, 11, 19, 28], "dimension_codes": ["decision_authority", "access_representation"], "source_ids": ["address"], "observations": [{"observation_id": "institutional_power_1850_1917_20261026:manifest1899:1", "statement": "Helmikuun manifestin mukaan Suomen valtiopäivien rooli yleisvaltakunnallisiksi säädettävissä laeissa oli neuvoa-antava. Suuri adressi vaati perustuslaillisiksi katsottujen oikeuksien palauttamista.", "source_ids": ["address"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["keisari", "valtiopäivät", "adressin kokoajat"], "affected_groups": ["Suomen asukkaat"], "mechanism_hypothesis": "Laaja osallistuminen ja muodollinen estovalta eivät olleet sama asia.", "case_limitations": "Ei väitettä kaiken Suomen lainsäädäntövallan poistumisesta. Adressin allekirjoitus ei osoita päätösvaltaa eikä koko väestön kantaa.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1850_1917_20261026:parliament1906", "primary_item_id": "aanioikeus-1906", "reuse_existing_item": true, "title": "Edustuksen laajeneminen ja hallitsijan säilynyt valta", "year_start": 1906, "year_end": 1906, "theme_ids": [8, 19, 22, 28], "dimension_codes": ["decision_authority", "access_representation"], "source_ids": ["constitution"], "observations": [{"observation_id": "institutional_power_1850_1917_20261026:parliament1906:1", "statement": "Valtiopäiväjärjestys määräsi yksikamarisesta eduskunnasta ja yhtäläisestä äänioikeudesta; myös naiset kuuluivat vaalioikeuden piiriin säädetyin ehdoin.", "source_ids": ["constitution"], "evidence_kind": "documented_institutional_claim", "inference": false}, {"observation_id": "institutional_power_1850_1917_20261026:parliament1906:2", "statement": "Hallitsijalla säilyi oikeus määrätä uudet vaalit ennen edustajakauden päättymistä.", "source_ids": ["constitution"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["eduskunta", "keisari", "äänioikeutetut"], "affected_groups": ["naiset", "aiemmin edustuksen ulkopuolella olleet"], "mechanism_hypothesis": "Edustuksen laajeneminen ei yksin siirtänyt kaikkea toimeenpano- tai estovaltaa eduskunnalle.", "case_limitations": "Vaalioikeuden poikkeukset säilyivät. Ei väitettä kaikkien asukkaiden äänioikeudesta tai senaatin parlamentaarisesta vastuusta. Säädösteksti tarkistettu jäljennöksestä.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1850_1917_20261026:july1917", "primary_item_id": "institutional_power_1850_1917_20261026:july1917", "reuse_existing_item": false, "title": "Heinäkuun valtalain hyväksyminen ja torjunta", "year_start": 1917, "year_end": 1917, "theme_ids": [8, 11, 28, 32], "dimension_codes": ["decision_authority", "oversight_accountability"], "source_ids": ["sovereignty"], "observations": [{"observation_id": "institutional_power_1850_1917_20261026:july1917:1", "statement": "Eduskunta hyväksyi valtalain 18.7.1917. Venäjän väliaikainen hallitus ei hyväksynyt ratkaisua vaan päätti hajottaa eduskunnan.", "source_ids": ["sovereignty"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["eduskunta", "Venäjän väliaikainen hallitus"], "affected_groups": ["äänestäjät", "edustajat"], "mechanism_hypothesis": "Hyväksytty päätös voi jäädä toteutumatta kilpailevan ylimmän vallan vuoksi.", "case_limitations": "Ei merkitä heinäkuun vallansiirtoa onnistuneeksi tai kiistattomaksi toimeenpanoksi.", "formal_authority_status": "adopted_but_contested_not_implemented_as_intended", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1850_1917_20261026:november1917", "primary_item_id": "institutional_power_1850_1917_20261026:november1917", "reuse_existing_item": false, "title": "Ylimmän vallan ja senaatin nimityksen muutos", "year_start": 1917, "year_end": 1917, "theme_ids": [8, 11, 28, 32], "dimension_codes": ["decision_authority", "access_representation"], "source_ids": ["sovereignty"], "observations": [{"observation_id": "institutional_power_1850_1917_20261026:november1917:1", "statement": "Eduskunta otti korkeimman vallan 15.11.1917. Sen nimittämän senaatin työ alkoi 27.11.1917.", "source_ids": ["sovereignty"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["eduskunta", "senaatti"], "affected_groups": ["edustajat", "Suomen asukkaat"], "mechanism_hypothesis": "Ylimmän vallan ja hallituksen muodostamisen kytkentä muuttui vuoden 1917 aikana.", "case_limitations": "Ei tarkoita hallinnon, järjestysvallan tai yhteiskunnallisen hyväksynnän välitöntä yhtenäistymistä. Heinäkuun ja marraskuun ratkaisut pidetään erillään.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1850_1917_20261026:municipal1917", "primary_item_id": "cleavages_1850_1917_20261023:municipal1917", "reuse_existing_item": true, "title": "Kunnallisen edustuksen yhtäläisyyden lainsäädäntö", "year_start": 1917, "year_end": 1917, "theme_ids": [8, 19, 22, 28], "dimension_codes": ["access_representation", "decision_authority"], "source_ids": ["municipal1917"], "observations": [{"observation_id": "institutional_power_1850_1917_20261026:municipal1917:1", "statement": "Vuoden 1917 kunnallislakien uudistus korvasi aiemman verovelvollisuuteen sidotun äänioikeuden yleisellä ja yhtäläisellä kunnallisella äänioikeudella.", "source_ids": ["municipal1917"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["eduskunta", "kunnat", "äänioikeutetut"], "affected_groups": ["aiemmin kunnallisen edustuksen ulkopuolella olleet"], "mechanism_hypothesis": "Edustuksen sääntömuutos saattoi muuttaa paikallisen resurssivallan käyttäjien joukkoa.", "case_limitations": "Retrospektiivinen lakitausta tarkistettu hakutulosotteesta, ei alkuperäisen vuoden 1917 lain koko tekstistä. Vaalien toteutus ja vaikutukset vaativat jatkotyön.", "formal_authority_status": "legislated_implementation_not_verified", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}], "limitations": ["Muodollinen toimivalta, toimeenpano ja tosiasiallinen vaikutusvalta erotetaan. Ei numeerisia vaikutusarvioita.", "Lähteet ovat pääosin viranomais- ja arkistohistorioita, eivät yksilöityjen päätösten vaikutustutkimuksia.", "Ei uutta teemaa; tapaukset kytketään olemassa oleviin teemoihin.", "Yksityinen omistus-, kirkollinen ja työnantajavalta sekä vähemmistöjen pääsy jäävät tässä aliedustetuiksi."], "open_tasks": ["Säätyedustuksen rajaukset ja valtiopäivien aloite-, vero- ja budjettivallan alkuperäissäädökset.", "Kunnalliset ääniluettelot, verotiedot ja pöytäkirjat: laissa säädetty ja käytetty valta.", "Nimitysvalta ja virkakelpoisuus sekä kirkon, yliopiston ja yritysten vallan kytkennät.", "Lainvalmistelun lausunnot, vaihtoehdot ja asiantuntijoiden valinta.", "Vuoden 1917 kunnallislakien alkuperäisteksti, voimaantulo ja ensimmäinen toteutunut vaali."]}$payload$::jsonb;
 e jsonb; urls text[]; d jsonb; h text; old_hash text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext(p->>'batch_id'));
 h := md5(p::text);
 SELECT data->>'payload_md5' INTO old_hash FROM public.dataset_meta WHERE id=p->>'batch_id';
 IF old_hash IS NOT NULL THEN
  IF old_hash<>h THEN RAISE EXCEPTION 'Batch payload changed; create a new version'; END IF;
  RETURN;
 END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(p->'entries') LOOP
  IF (e->>'year_start')::int<1850 OR (e->>'year_end')::int>1917 THEN RAISE EXCEPTION 'Year outside collection'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(e->'dimension_codes') x WHERE NOT (p->'taxonomy' ? x)) THEN RAISE EXCEPTION 'Unknown dimension'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(e->'source_ids') x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'sources') s WHERE s->>'source_id'=x)) THEN RAISE EXCEPTION 'Unknown source'; END IF;
  SELECT array_agg(s->>'url' ORDER BY s->>'source_id') INTO urls FROM jsonb_array_elements(p->'sources') s WHERE e->'source_ids' ? (s->>'source_id');
  IF (e->>'reuse_existing_item')::boolean THEN
   IF NOT EXISTS(SELECT 1 FROM public.items WHERE id=e->>'primary_item_id') THEN RAISE EXCEPTION 'Missing existing item %',e->>'primary_item_id'; END IF;
   UPDATE public.items SET sources=ARRAY(SELECT DISTINCT u FROM unnest(sources||urls) u ORDER BY u),updated_at=now() WHERE id=e->>'primary_item_id' AND NOT sources @> urls;
  ELSE
   INSERT INTO public.items(id,title,year_start,year_end,type,domains,phase,problem,mechanism,effects,long_effect,current_relevance,importance,confidence,sources,subtype,evidence_confidence,interpretation_confidence)
   VALUES(e->>'primary_item_id',e->>'title',(e->>'year_start')::int,(e->>'year_end')::int,'tapahtuma',ARRAY['institutionaalinen valta','julkinen valta','oikeusvaltio'],'1850–1917',
    (SELECT string_agg(o->>'statement',' ' ORDER BY n) FROM jsonb_array_elements(e->'observations') WITH ORDINALITY x(o,n)),
    'Tulkintahypoteesi: '||(e->>'mechanism_hypothesis'),ARRAY['Dokumentoitu institutionaalinen muutos; vaikutuksen suuruutta ei ole tunnistettu.'],e->>'case_limitations','Muodollisen toimivallan, edustuksen ja tosiasiallisen vaikutusvallan erottaminen.',3,'kohtalainen',urls,'institutional_power_history','kohtalainen','kehittyvä');
  END IF;
  d := e || jsonb_build_object('batch_id',p->>'batch_id','taxonomy_id',p->>'taxonomy_id','case_type','historical_institutional_power','sources',to_jsonb(urls),'item_ids',jsonb_build_array(e->>'primary_item_id')||(e->'related_item_ids'),'limitations',(p->'limitations')||jsonb_build_array(e->>'case_limitations'),'measurement_status','qualitative_documented_case','causal_confirmation',false,'numeric_effect',null,'mechanism_link_status','hypothesis_context','population_prevalence_measured',false);
  IF EXISTS(SELECT 1 FROM public.atlas_mechanism_cases WHERE data->>'case_key'=e->>'case_key') THEN RAISE EXCEPTION 'Case already exists outside manifest'; END IF;
  INSERT INTO public.atlas_mechanism_cases(title,year_start,year_end,kind,status,published,primary_item_id,data)
   VALUES(e->>'title',(e->>'year_start')::int,(e->>'year_end')::int,'history','hypothesis',true,e->>'primary_item_id',d);
 END LOOP;
 INSERT INTO public.dataset_meta(id,data) VALUES(p->>'batch_id',p||jsonb_build_object('payload_md5',h,'imported_at',now()));
END $import$;
COMMIT;
SELECT count(*) AS cases,count(DISTINCT primary_item_id) AS linked_items,sum(jsonb_array_length(data->'observations')) AS observations,count(*) FILTER(WHERE (data->>'reuse_existing_item')::boolean) AS reused_items,count(*) FILTER(WHERE NOT (data->>'reuse_existing_item')::boolean) AS new_items FROM public.atlas_mechanism_cases WHERE data->>'batch_id'='institutional_power_1850_1917_20261026';
